"""Render retained four-track evidence, with pending obligations explicit."""
import html,statistics
from datetime import datetime,timezone
from v5_support import ROOT,BASE,DOCS,read,write,sha
def table(headers,rows):
    return '<table><thead><tr>'+''.join('<th>'+html.escape(str(x))+'</th>'for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(str(x))+'</td>'for x in row)+'</tr>'for row in rows)+'</tbody></table>'
def build():
    sections=[];evidence={};fits=[];evaluations=[];rollouts=[];blind_rows=[];pressure=[];native_times=[];drift_rows=[]
    def keep(path):evidence[str(path.relative_to(ROOT))]=sha(path);return read(path)
    complete=(DOCS/'completion-audit.json').exists()and read(DOCS/'completion-audit.json')['status']=='complete'
    for arm in ['v5-raw','v5-multilevel','v5-spectrum']:
        path=BASE/(arm+'-study-01/receipt.json')
        if path.exists():
            d=keep(path);history=keep(path.parent/'train/history.json');work=history['optimizer_work'];fits.append([arm,d['status'],648,d['optimizer_updates'],work['network_forwards'],work['forward_cells'],all(d['artifact_parity'].values())])
        else:fits.append([arm,'Pending','','','','',''])
    sections.append('<h2>Matched training contrasts</h2><p>Three linear 3×3×3 convolutions (1→4→4→1), no learned biases, plus a fixed q/8 skip. All models share the exact 648-parameter initial state, optimizer schedule and 1,600 original small-grid sampling choices. Another 800 updates sample larger tiers. Reported cells are actual optimizer forwards; the spectral view changes larger-parent exposure and does not imply equal total cell work. Coarse conditioning is a frozen CPU preprocessing cycle; inference still pays its full hierarchy cost.</p>'+table(['Arm','State','Parameters','CUDA updates','Optimizer forwards','Forward cells','Fresh CPU artifact parity'],fits))
    view=BASE/'spectrum-training-view-01/manifest.json'
    if view.exists():
        d=keep(view);sections.append('<h2>Explicit spatial training data</h2><p>The expanded view retains all '+str(d['retained_v3_parents'])+' original parents and adds '+str(d['added_spectral_parents'])+' reserved spatial-band parents. Six seeded Neumann cosine modes define each independent pressure pattern. Mode bands 1–3, 4–7 and 8–12 and cubic/rectangular grids vary spatial content explicitly. Wavelength along a nonconstant axis is 2Nh/k metres. These are exact-operator pressure equations, not evolved fluid trajectories; synthetic frame slots are independent patterns. Same-equation spectral labels are checked against the analytic fields, and every decoded field hash is verified. Encoded fitting data: '+f"{d['encoded_total_bytes']/1024**2:.2f}"+' MiB. Native forcing scenes remain a separate independent evaluation.</p>')
    for p in sorted((BASE/'evaluation-final').glob('*.json')):
        d=keep(p);rows=d['rows'];old=[r for r in rows if not r['population'].startswith('v5-')];native=[r for r in rows if r['population']=='v5-native-development'];spatial=[r for r in rows if r['population']=='v5-spectrum-development']
        evaluations.append([d['identifier'],*[f"{sum(r['qualified']for r in g)}/{len(g)}"for g in [old,native,spatial]],
            statistics.median(r['coarse_calls']for r in native),statistics.median(r['coarse_calls']for r in spatial),f"{max(r['pressure_relative_l2']for r in rows):.3g}"])
    if evaluations:sections.append('<h2>Returned-field development qualification</h2><p>Every policy sees the same 192 retained requests, ten reserved native cold/warm requests and eighteen reserved wavelength patterns. Both unchanged residual and predicted-divergence gates are evaluated on the actual returned float64 pressure. No failed case is hidden. The initialization control is explicitly untrained and is not counted as a managed fit. These are development comparisons; fresh blind evaluation follows frozen selection.</p>'+table(['Policy','Retained gates','New native gates','New spatial gates','Native median cycles','Spatial median cycles','Worst pressure rel. L2'],evaluations))
    for p in sorted((BASE/'blind-evaluation').glob('*.json')):
        d=keep(p);rows=d['rows'];groups=[[r for r in rows if r['population']=='v5-native-blind'],[r for r in rows if r['population']=='v5-spectrum-blind']]
        blind_rows.append([d['identifier'],*[f"{sum(r['qualified']for r in g)}/{len(g)}"for g in groups],
            statistics.median(r['coarse_calls']for r in groups[0]),statistics.median(r['coarse_calls']for r in groups[1]),f"{max(r['pressure_relative_l2']for r in rows):.3g}"])
    if blind_rows:sections.insert(0,'<h2>Fresh blind qualification</h2><p>Fourteen frozen operating points, including numerical and untrained controls, each pass the same ten new native requests and twenty-four new spatial patterns. Five native forcing scenes and twelve spatial-pattern parents were reserved before fitting; none entered training. Every tensor input has the same population hash across all policies. This establishes coverage on the pilot population. Because the controls also pass, improvements must be assessed through correction work, pressure error and total time.</p>'+table(['Policy','Native gates','Spatial gates','Native median cycles','Spatial median cycles','Worst pressure rel. L2'],blind_rows))
    for p in sorted((BASE/'quiet-pressure').glob('*.json')):
        d=keep(p);pressure.append(dict(identifier=d['identifier'],population=d['population'],parameters=d['parameters'],**d['summary']))
    if pressure:sections.append('<h2>Matched pressure-policy timing</h2><p>Two separate populations: 128 retained requests on grids of 5–16 cells per axis, and ten fresh native requests on grids from 32³ through 128³. Each has one whole-population warmup and three independent timed repeats per request. CPU 23, one thread. All network/coarse work, conversions, stopping and a common independent returned-pressure gate count. Loading, model setup and label generation do not. Reuse is disabled for these independent-request measurements. Supplemental C53 and v2 controls with six coarse nodes per axis provide a matched comparison with strong prior frontier points. Rejected points remain visible and are excluded from qualified frontiers.</p>'+table(['Population','Policy','Parameters','Gates passed','Median ms','Worst pressure rel. L2'],[[r['population'],r['identifier'],r['parameters'],f"{r['qualified']}/{r['cases']}",f"{r['median_ms']:.3f}",f"{r['worst_pressure_relative_l2']:.3g}"]for r in pressure]))
    timing=DOCS/'timing-reservation.json'
    if timing.exists():
        for row in keep(timing)['rows']:
            prefix=row['trajectory_id']+'-';groups={}
            for p in sorted((BASE/'quiet-native').glob(prefix+'*/receipt.json')):
                key=p.parent.name[len(prefix):].rsplit('-r',1)[0];groups.setdefault(key,[]).append(keep(p))
            for key,ds in groups.items():
                medians=[statistics.median(f['frame_seconds']for f in d['frames'])for d in ds]
                native_times.append(dict(counts=row['scene']['counts'],steps=row['scene']['steps'],identifier=key,repeats=len(ds),accepted_repeats=sum(d['status']=='completed'for d in ds),
                    median_seconds=statistics.median(medians),min_seconds=min(medians),max_seconds=max(medians)))
    if native_times:sections.append('<h2>Full native fluid-step timing</h2><p>Matched blind-scene prefixes, three balanced-order serial repeats per method. The 64³ and rectangular episodes advance 32 steps; the 128³ episode is a bounded four-step comparison. Statistics are medians of per-run frame medians, with the observed range. Native preparation, RHS assembly, binary exchange, pressure policy, host gates and projection count. GUI, loading, teacher labels and state exports do not. The original v4 full-model hybrid uses its unchanged adapter. A rejected episode is an attempted cost and cannot establish a usable speedup.</p>'+table(['Grid cells','Steps/repeat','Method','Completed repeats','Median seconds/step','Run range'],[['×'.join(map(str,r['counts'])),r['steps'],r['identifier'],f"{r['accepted_repeats']}/{r['repeats']}",f"{r['median_seconds']:.4f}",f"{r['min_seconds']:.4f}–{r['max_seconds']:.4f}"]for r in native_times]))
    outcomes=[]
    for shape in [[64]*3,[75,51,35],[128]*3]:
        group={r['identifier']:r for r in native_times if r['counts']==shape and r['repeats']==3 and r['accepted_repeats']==3}
        if 'legacy-v3'in group and 'selected-optimized'in group:
            before=group['legacy-v3']['median_seconds'];after=group['selected-optimized']['median_seconds']
            outcomes.append('On '+html.escape('×'.join(map(str,shape)))+' cells, the optimized tiny fresh-solve policy takes '+f'{after:.3f}'+' seconds per native step versus '+f'{before:.3f}'+' for the previous full-model hybrid ('+f'{abs(100*(1-after/before)):.1f}'+('% lower'if after<=before else'% higher')+' in this matched test).')
    if outcomes:sections.insert(0,'<h2>Measured outcomes</h2><p>'+' '.join(outcomes)+'</p><p>The new local model has 648 parameters versus 371,214 in the prior full-model hybrid. Post-coarse training reduces median hierarchy work on the 28 new development requests from four cycles to three. Every blinded control also passes, and the untrained tiny control remains visible. Parameter count and work reductions are separate from measured time gains. Recycling saves work but its runtime benefit varies; retained-space projection and maintenance count in every native timing.</p>')
    profile_rows=[]
    for shape in [[64]*3,[75,51,35],[128]*3]:
        callbacks=[]
        for p in (BASE/'quiet-native').glob('v5-timing-'+'x'.join(map(str,shape))+'-selected-optimized-r*/receipt.json'):callbacks.extend(keep(p)['callbacks'])
        if callbacks:
            profile_rows.append(['×'.join(map(str,shape)),*[f"{1000*statistics.median(c[k]for c in callbacks):.2f}"for k in ['input_read_seconds','assembly_seconds','method_seconds','output_send_seconds']],
                *[f"{1000*statistics.median(c['work'][k]for c in callbacks):.2f}"for k in ['coarse_seconds','network_seconds','operator_seconds']]])
    if profile_rows:sections.append('<h2>Where native callback time goes</h2><p>Median instrumented milliseconds over final fresh optimized native callbacks. Hierarchy, local correction and outer operator columns are components inside the method column; they must not be added to it again. The local correction includes feature preparation and reconstruction. The remaining method work includes GCR orthogonalization, validation and stopping. Input reads, RHS assembly and output sends occur outside the method but inside native pressure waiting time. The separate 128³ duplicate-audit variant measures an additional client residual diagnostic while both solver and native gates remain enabled.</p>'+table(['Grid cells','Input read ms','RHS assembly ms','Method ms','Output send ms','Hierarchy ms','Local correction ms','Outer operator ms'],profile_rows))
    for p in sorted((BASE/'rollouts-final').glob('*/receipt.json')):
        d=keep(p);calls=[c['work']for c in d['callbacks']]
        rollouts.append([p.parent.name,d['status'],sum(f['advanced']for f in d['frames']),d['scene']['steps'],sum(w['coarse_calls']for w in calls),sum(w['network_calls']for w in calls),max(w.get('cache_bytes',0)for w in calls)])
    if rollouts:sections.append('<h2>Consecutive native steps</h2><p>Each episode starts cold with empty direction storage. The GCR basis is bounded at zero, two or four directions and commits only after the native host accepts and advances the step. Pressure warm starts remain enabled for every method. Reference and candidate trajectories advance independently with the same scene and dt = 1/60 s. A 32-step episode covers 0.533 simulated seconds; it does not establish an application accuracy horizon.</p>'+table(['Episode','Outcome','Advanced','Requested','Hierarchy cycles','CNN calls','Peak stored basis bytes'],rollouts))
    blind_work=[]
    for row in read(DOCS/'scene-reservation.json')['rows']:
        if row['population']!='rollout-blind':continue
        values=[]
        for policy in ['tiny-fresh','tiny-tail4','tiny-recycled','numerical-fresh','numerical-recycled']:
            p=BASE/'rollouts-blind'/(row['trajectory_id']+'-'+policy)/'receipt.json'
            if not p.exists():break
            d=keep(p);values.append(sum(c['work']['coarse_calls']for c in d['callbacks']))
        if len(values)==5:blind_work.append(['×'.join(map(str,row['scene']['counts'])),*values])
    if blind_work:sections.append('<h2>Useful direction retention on blind trajectories</h2><p>Every track advances all 32 requested steps. The existing pressure warm start is shared by every method. The useful-direction strategy ranks stored directions by their mean-free pressure contribution in the current accepted solve, avoiding wholesale replacement by new residual-complement directions. Across the three blind scenes, the tiny model uses 324 hierarchy cycles with fresh solves and 282 with useful-direction reuse (13.0% fewer). Numerical controls use 436 and 376 cycles respectively (13.8% fewer). These are work reductions; basis projection, scoring, copying and storage can offset them in runtime. Four stored direction/image pairs occupy 16 MiB at 64³ and 128 MiB at 128³, in addition to ordinary solver workspace.</p>'+table(['Grid cells','Tiny fresh','Tiny newest4','Tiny useful4','Numerical fresh','Numerical useful4'],blind_work))
    for p in sorted((BASE/'drift-blind').glob('*.json')):
        d=keep(p)
        if not d['rows']:continue
        r=d['rows'][-1];drift_rows.append([p.stem,d['matched_accepted_steps'],r['time_s'],*[f"{r[k]['relative_l2']:.3g}"if r[k]['relative_l2']is not None else'undefined'for k in ['pressure','velocity','tracer']]])
    if drift_rows:sections.append('<h2>Short blind trajectory drift</h2><p>Full pressure, staggered velocity and tracer fields are independently advanced against the spectral reference, then decoded and hash-verified. All comparisons cover 32 accepted steps, or 0.533 simulated seconds. Pressure gauges are removed. Velocity and tracer differences remain comparable between fresh and recycled solves in this pilot; no general drift improvement or application acceptance threshold is established.</p>'+table(['Track','Accepted steps','Simulated seconds','Final pressure rel. L2','Final velocity rel. L2','Final tracer rel. L2'],drift_rows))
    profile=BASE/'hierarchy-profile-01.json'
    if profile.exists():
        d=keep(profile);sections.append('<h2>Execution diagnosis</h2><p>The instrumented 128³ hierarchy cycle spends roughly two-thirds of its time in operator actions. The optimization uses the identical fine edge stencil directly and avoids applying the operator to an initially zero field at each level. Restriction, prolongation and exact Galerkin coarse operators are retained. Independent cube, odd-grid and rectangular tests check complete-cycle parity. Native callback instrumentation separately records input reads, RHS assembly, output sends and optional redundant residual diagnostics. Independent native acceptance remains active throughout.</p>')
    if(DOCS/'model-selection.json').exists():
        d=keep(DOCS/'model-selection.json');sections.append('<h2>Frozen model selection</h2><p>Selected '+html.escape(d['selected']['arm'])+' using development gate coverage, retained coverage and correction work. No further fits are allowed after this selection. Reuse capacity and execution are qualified before new blind capture.</p>')
        arm=d['selected']['arm'];sections.append('<p>Selected research artifacts: <a href="../../../runs/pressure-methods-v5/'+arm+'-study-01/restore/weights.npz">CPU weights</a> · <a href="../../../runs/pressure-methods-v5/entries/'+arm+'.json">Exact model/source entry</a> · <a href="../../../runs/pressure-methods-v5/'+arm+'-project-02/project.json">Captured training Project</a>. The models start from the same seeded tiny network, with no C53 weight reuse or distillation. A nonoperative inherited controller label in the raw arm is disclosed in <a href="../../../runs/pressure-methods-v5/v5-raw-controller-metadata-clarification.json">its metadata clarification</a>; checkpoint-000 proves the actual shared initialization.</p>')
    if(DOCS/'selection.json').exists():
        d=keep(DOCS/'selection.json');sections.append('<p>The frozen configuration uses four useful directions, the direct fine-grid stencil and channels-last local inference. All blinded variants remain reported. The wavelength-augmented fit won a small pressure-error tie-break against the native-only post-coarse fit; both had the same development coverage and median work. This does not establish a clear additional benefit from wavelength augmentation in this recipe.</p>')
    sections.append('<h2>Qualification correction and preserved exploratory evidence</h2><p>A deliberately large-base equation exposed an increment-versus-returned-pressure precision error in the initial dispatcher. The regression fails for the original wrapper and passes for the corrected dispatcher, which recomputes RHS minus the operator applied to the actual rounded pressure during convergence and final qualification. The original preliminary evaluations are retained and excluded from the final matrix. Native Rust gates were unchanged and no rejected native step advanced. Training fits are unaffected.</p>')
    erratum=keep(DOCS/'prior-report-erratum.json');sections.append('<p>Correction to prior v4 report prose: the multilevel/CNN hybrid retained all '+str(erratum['retained_cases'])+' prior requests, with '+str(erratum['total_development_qualified'])+'/'+str(erratum['total_development_cases'])+' total development qualifications. Its statement that one retained request failed was a table-reading error. Prior raw evidence and publication hashes are preserved. <a href="prior-report-erratum.json">Exact correction and source</a>.</p>')
    if(DOCS/'figure-evidence.json').exists():
        fig=keep(DOCS/'figure-evidence.json')
        for name in fig.get('names',[]):sections.append('<figure><img src="figures/'+html.escape(name)+'.svg" alt="'+html.escape(name)+'"><figcaption><a href="figures/'+html.escape(name)+'.pdf">PDF</a></figcaption></figure>')
    if complete:
        keep(DOCS/'final-audit.json');keep(DOCS/'completion-audit.json');sections.append('<p><a href="final-audit.json">Final evidence and fresh Run custody audit</a> · <a href="completion-audit.json">Four-objective completion audit</a> · <a href="figure-evidence.json">Figure provenance</a></p>')
    boundary='All four requested explorations are complete and audited.'if complete else'Active: development and blind qualification are complete; isolated repeated timing and the final evidence audit are being completed.'
    sections.append('<h2>Completion boundary</h2><p>'+boundary+' No model promotion or application drift acceptance is claimed. Training stops at 128³; production 256³/512³/1024³ deployment is outside this series.</p>')
    payload=dict(status='complete'if complete else'active',updated_utc=datetime.now(timezone.utc).isoformat(),successful_fits=sum(r[1]=='completed'for r in fits),fits=fits,evaluations=evaluations,blind=blind_rows,pressure_timing=pressure,native_timing=native_times,rollouts=rollouts,blind_work=blind_work,blind_drift=drift_rows,evidence=evidence,source_sha256=sha(__file__),promotion=False)
    body='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Pressure methods v5</title><style>body{font:16px system-ui;max-width:1400px;margin:32px auto;padding:0 24px;background:#f7fafb;color:#183744}p{line-height:1.55;max-width:1100px}table{width:100%;border-collapse:collapse;font-size:13px;margin:20px 0 36px}th,td{padding:8px;text-align:left;border-bottom:1px solid #ccd9df}th{background:#e4eef1}img{width:100%;height:auto}figure{margin:24px 0}</style><h1>Pressure methods v5: lightweight multilevel correction and timestep reuse</h1><p>'+boundary+' Updated '+html.escape(payload['updated_utc'])+'.</p>'+''.join(sections)+'<p><a href="results.json">Machine-readable evidence</a> · <a href="campaign.json">Four required tracks</a> · <a href="requested-scope.json">Original requested scope</a> · <a href="../pressure-methods-v4/results.html">Preserved prior report</a></p></html>'
    (DOCS/'results.html').write_text(body);write(DOCS/'results.json',payload);print('Rendered four-track report;',payload['successful_fits'],'completed fits',flush=True)
if __name__=='__main__':build()
